const G = (text) => ({ text, tone: 'good' }), B = (text) => ({ text, tone: 'bad' });
const L = (at, text, tone, side, dy) => ({ at, text, tone: tone || 'good', side, dy });
const AR = (at, dir, len, tone, off) => ({ at, dir, len, tone: tone || 'good', off });
const ROT = (at, from, to, tone, r, dy) => ({ rot: true, at, from, to, tone: tone || 'good', r, dy });
// reference lines: LN(from, to, tone, [extend back, extend forward]); PLUMB straight down to the ground from a point
